INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9018fcf8-681d-4bed-9305-0541dbe83201', '17e61b54-6523-41b3-b52a-35bb01a35a2c', 0, 'Short names are always rejected by ansible-lint with no way to allow them');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4e1dc67c-5231-4979-9a57-c0f8ebb715ed', '17e61b54-6523-41b3-b52a-35bb01a35a2c', 1, 'FQCNs remove ambiguity when multiple installed collections ship a module with the same short name, and make the playbook''s dependency on a specific collection explicit');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7e22540d-1959-49d9-835d-6847ddf6b605', '17e61b54-6523-41b3-b52a-35bb01a35a2c', 2, 'FQCNs run faster than short module names at task execution time');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('45ff33d4-1be9-4e3c-bbcb-a4eab7c5d7d7', '17e61b54-6523-41b3-b52a-35bb01a35a2c', 3, 'Short names only work inside roles, never in top-level playbooks');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('95927868-a69c-4862-b43f-2048c110addb', 'd56b555f-db52-478f-bd56-959c08ef7183', 0, 'Installs a fixed, hardcoded old version to the current directory');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f092dc81-a5fc-474a-9876-e6a19afa9f4a', 'd56b555f-db52-478f-bd56-959c08ef7183', 1, 'Installs the latest available version of the collection to the first path listed in COLLECTIONS_PATHS (by default, ~/.ansible/collections)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('555044be-d002-47e9-9494-0bebd15fa607', 'd56b555f-db52-478f-bd56-959c08ef7183', 2, 'Fails immediately, since a version must always be specified');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('94f50c33-4973-432c-9f3d-83e8b8d93ead', 'd56b555f-db52-478f-bd56-959c08ef7183', 3, 'Installs every collection published under the community.* namespace');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f9ceb413-c6d9-40e8-bf71-be30bf3ee357', 'a38913a7-ef13-43cc-a508-23cf981d9986', 0, 'By appending a version specifier, e.g. `community.general:>=5.0.0,<6.0.0`');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6fdb183f-0edf-4f5e-b96b-ff0585d09331', 'a38913a7-ef13-43cc-a508-23cf981d9986', 1, 'Version ranges are not supported; only exact single versions can be installed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('eb1d65af-c285-48a8-973e-420c21a80362', 'a38913a7-ef13-43cc-a508-23cf981d9986', 2, 'By setting ANSIBLE_COLLECTIONS_VERSION as an environment variable');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ba70a724-54bf-4762-b587-9b201a59827f', 'a38913a7-ef13-43cc-a508-23cf981d9986', 3, 'By editing ansible.cfg''s [defaults] section only');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('66e3cdd3-8292-425e-88da-4afc36e389bc', '709935e3-8b0c-4a9b-aa63-08141f3d6390', 0, 'A single `ansible-galaxy install -r requirements.yml` command installs both roles and collections together automatically');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7ec5bdac-e865-44b7-8851-2dac58cf5896', '709935e3-8b0c-4a9b-aa63-08141f3d6390', 1, 'Roles and collections must be installed with separate commands — `ansible-galaxy role install -r requirements.yml` installs only the roles, `ansible-galaxy collection install -r requirements.yml` installs only the collections');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0e91e9a8-924a-427d-9d95-121e21685121', '709935e3-8b0c-4a9b-aa63-08141f3d6390', 2, 'Only collections can be listed in requirements.yml; roles require a completely separate file format');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3842633f-0e41-4c30-a057-242e7894ad9b', '709935e3-8b0c-4a9b-aa63-08141f3d6390', 3, 'requirements.yml can only reference content already present locally, never remote sources');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f5416447-13c6-461c-913b-6a50690c85d2', '81f46114-1d89-4a51-b90d-8ad1f4c2f43a', 0, 'Only Ansible Galaxy — no other source is ever supported');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d954d50e-4aa2-41be-8551-c36f38ff475e', '81f46114-1d89-4a51-b90d-8ad1f4c2f43a', 1, 'Git repositories, direct URLs to a tarball, and local tarball files, in addition to Galaxy/Automation Hub');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('25c8a798-58bd-4cc9-953d-ec0626292175', '81f46114-1d89-4a51-b90d-8ad1f4c2f43a', 2, 'Only a private Automation Hub instance, never Galaxy or Git');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f7c4daca-19f1-431e-8390-8adf17ff4e73', '81f46114-1d89-4a51-b90d-8ad1f4c2f43a', 3, 'Only local filesystem paths, never any network source');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e7b7b385-be04-41b5-b4c4-ccba5d5c8713', 'fa40fbf8-68ba-4a12-95c4-29a454c59462', 0, 'It installs the collections into the project-local ./collections directory instead of the default COLLECTIONS_PATHS location');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cd83f8ba-ac75-4124-beaa-8854de80ef54', 'fa40fbf8-68ba-4a12-95c4-29a454c59462', 1, 'It validates the requirements.yml syntax without actually installing anything');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3f2d4d6c-3d9d-40e0-a015-4b6b2b7722ab', 'fa40fbf8-68ba-4a12-95c4-29a454c59462', 2, 'It installs collections only for the current user''s default role path');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5d583e5d-dac5-43af-ad91-485c1c3e3ffc', 'fa40fbf8-68ba-4a12-95c4-29a454c59462', 3, 'The -p flag has no effect on collection installs, only on role installs');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('26957d5a-eb92-4a74-8fc8-5bea756a3509', '84192c73-bf63-4e49-bc1a-a869b0cbb8e0', 0, 'A Role can only contain tasks, while a Collection can only contain variables');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ce252aa7-8aa9-4981-ba11-11e63856c778', '84192c73-bf63-4e49-bc1a-a869b0cbb8e0', 1, 'A Collection is a distributable package that can bundle multiple roles, modules, plugins, and playbooks together under one namespace; a Role is a single reusable unit of tasks/handlers/templates typically bundled inside (or alongside) a collection');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('17141fd6-7b34-4539-b7cf-53f02a56ebb0', '84192c73-bf63-4e49-bc1a-a869b0cbb8e0', 2, 'Roles and Collections are two names for exactly the same artifact with no structural difference');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('79d7aabc-28de-4661-a847-436426173eaf', '84192c73-bf63-4e49-bc1a-a869b0cbb8e0', 3, 'A Collection cannot be published to Galaxy, only Roles can');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3a3adf79-3b69-4ec8-ade5-aeaceacf47b8', 'f8ae77d0-5b95-4c8e-9142-1d069b690db3', 0, 'ansible-galaxy collection list, plus ansible-doc <fqcn> for details on a specific module');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fe94d64e-4c72-4a84-a3bc-634f98b027d1', 'f8ae77d0-5b95-4c8e-9142-1d069b690db3', 1, 'There is no way to enumerate installed collection content; it must be looked up in online docs only');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a596f65f-fd22-41fc-b566-7a19a04425f0', 'f8ae77d0-5b95-4c8e-9142-1d069b690db3', 2, 'ansible-inventory --list-collections');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('440d47cf-d909-4d65-8c1e-a010e0cb5162', 'f8ae77d0-5b95-4c8e-9142-1d069b690db3', 3, 'ansible-config dump --collections');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
