INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ea7bb029-c916-48b3-93c9-255993d1ffb8', '8775b754-1b8a-4286-8c08-196e40921748', 0, 'A Python virtual environment created by pip on the control node');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7d8d5114-43b2-445b-b5c4-e098ffe44998', '8775b754-1b8a-4286-8c08-196e40921748', 1, 'An OCI-compliant container image that bundles ansible-core, Ansible Content Collections, and their Python/system-level dependencies into one portable, versioned control-node runtime');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3cb0f663-cf5a-4ab0-84f5-ee29f0088c20', '8775b754-1b8a-4286-8c08-196e40921748', 2, 'A dedicated managed node used only for testing playbooks before production');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('50f6987d-64a0-4e5b-b444-ea52c3928ec8', '8775b754-1b8a-4286-8c08-196e40921748', 3, 'A synonym for an Ansible inventory group');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('303a75ec-7001-4d97-aca0-d57ca60fea15', '4a68a748-2de0-424d-9bfb-fc95ca24c3b9', 0, 'They make playbooks run without needing an inventory file');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('419b85d3-2a1e-4ec8-a474-a61d982dcded', '4a68a748-2de0-424d-9bfb-fc95ca24c3b9', 1, 'They eliminate ''it works on my control node'' dependency drift — every run uses the exact same pinned Ansible version, collections, and Python/system packages, packaged once and reused anywhere a container runtime is available');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('29eb5bc0-b829-4a88-bdd4-8fa08be2d26f', '4a68a748-2de0-424d-9bfb-fc95ca24c3b9', 2, 'They remove the need for SSH connectivity to managed nodes entirely');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('536a000e-c111-43a5-9a43-259d2eee7257', '4a68a748-2de0-424d-9bfb-fc95ca24c3b9', 3, 'They allow playbooks to run without any Python interpreter on managed nodes');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
