INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f949ecdd-d63d-4bdb-ad79-ab2e26090245', '2e718c11-c59a-485e-99fb-2ff3ec328777', 1, 'It builds Execution Environment container images from a YAML definition file describing dependencies (collections, Python packages, system packages)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('67973c19-b6ab-4fe4-b262-a39ed83c5eaa', '2e718c11-c59a-485e-99fb-2ff3ec328777', 2, 'It converts YAML playbooks into JSON');
