INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7bc83fb7-af92-4166-bae4-5fb4befe717a', '04dc260e-ee58-47c2-9870-f2e2ec9231de', 0, 'Nothing — EEs guarantee identical behavior automatically regardless of anything else');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ce749a9d-daef-488d-9996-f7646dc5acda', '04dc260e-ee58-47c2-9870-f2e2ec9231de', 1, 'All three must pull and run the exact same EE image (same tag/digest); if they pull different versions of the image, dependency versions can differ between runs');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('79731331-8d69-43ce-9b65-b315cccb2369', '04dc260e-ee58-47c2-9870-f2e2ec9231de', 2, 'Only the CI pipeline needs the EE; Automation Controller ignores EE images');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8b02d5bb-f8ad-427d-9067-ed058efcde7f', '04dc260e-ee58-47c2-9870-f2e2ec9231de', 3, 'The playbook must be rewritten separately for each execution context');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
