INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d90c600b-fdfb-43c9-9bc9-d488c672357b', '6ea64fd5-1a0d-454b-abb1-a43b6afb1546', 0, 'Nothing was needed; ansible-core has no external dependencies');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cd83ab2d-1d91-4f04-9b33-b7a26cb20b14', '6ea64fd5-1a0d-454b-abb1-a43b6afb1546', 1, 'Manually replicate the same pip/ansible-galaxy installs, versions, and OS packages on every machine (or via config management), which was error-prone and easy to let drift');
