INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3553ae8f-9e27-49c8-9296-6e0e223302e9', 'c6e02e5b-19bd-4269-855d-7c456b119f5d', 1, 'No — the documented subcommand list (welcome, run, exec, images, doc, config, collections, builder, replay, inventory, lint, settings) does not include a `doctor` subcommand; this is not a real ansible-navigator command');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1f41dcd3-f58a-4a31-aacb-209efec44206', 'c6e02e5b-19bd-4269-855d-7c456b119f5d', 2, 'Yes, but only when running inside Automation Controller');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e919f07a-2088-433b-a1b7-7e5947c2c42a', 'c6e02e5b-19bd-4269-855d-7c456b119f5d', 3, 'No, because `doctor` was renamed to `exec` in recent releases');
