INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('62d3b1c6-bb3b-4719-bb93-6a4885af5aff', '757f31d2-c304-4114-9209-b14e3cc710b1', 1, 'Output is printed to the terminal much like plain `ansible-playbook`, instead of launching the browsable TUI — useful for CI/CD pipelines where there''s no interactive terminal');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6ddf3b2d-475b-4ead-a036-b498ae8fff89', '757f31d2-c304-4114-9209-b14e3cc710b1', 2, 'It forces the playbook to run without an Execution Environment');
