INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f71a5a47-7ba5-4165-a273-f274bd8103bc', '7139fe90-c1e1-43a8-92b8-ecc7384fd15c', 1, 'Built-in defaults, settings file, environment variables, CLI parameters');
