INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('900cde6e-448f-4867-9f19-81f21a8f4a31', 'f247d330-802c-4b6f-a78d-fa8c8b1e84b1', 0, 'Only in /etc/ansible-navigator.yml, nowhere else');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7d7111ad-0c8d-45d3-8e9a-9c48d8c1f23a', 'f247d330-802c-4b6f-a78d-fa8c8b1e84b1', 1, 'It checks the current project directory (./ansible-navigator.<ext>) before falling back to the home directory (~/.ansible-navigator.<ext>)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('42c3e1be-93fc-4539-86e6-8f5882a2cf6b', 'f247d330-802c-4b6f-a78d-fa8c8b1e84b1', 2, 'Only in the home directory; the current directory is never checked');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ce24372e-a2c4-40f2-8d92-04d9cc853eeb', 'f247d330-802c-4b6f-a78d-fa8c8b1e84b1', 3, 'It never uses a settings file unless ANSIBLE_NAVIGATOR_CONFIG is explicitly set');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
