INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('805717c1-81be-44f9-9427-80f2891b07ca', '4b3bf1bb-256b-4415-897a-1e551e282461', 0, 'Always re-pulls the image from the registry regardless of whether it''s already present locally');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ab7d0100-1d94-4cab-8c7f-9edee41c8009', '4b3bf1bb-256b-4415-897a-1e551e282461', 1, 'Only pulls the image if it is not already available locally, avoiding an unnecessary re-pull of an image that''s already present');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('216f27d5-10d8-4164-8ec9-8f2f9e9e8b94', '4b3bf1bb-256b-4415-897a-1e551e282461', 2, 'Never pulls the image under any circumstance, even if missing, causing the run to fail');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('484aed55-57fe-4b4a-8eb5-d6ffe09d7f51', '4b3bf1bb-256b-4415-897a-1e551e282461', 3, 'Pulls a different, smaller fallback image if the requested one is missing');
