INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('910c8714-c677-4612-9c74-e8688fe2278c', 'e43a9e37-44de-43a4-8c70-41982bfcdf63', 1, 'The current Ansible configuration (equivalent in spirit to `ansible-config`, but explorable via navigator''s interface)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e1c8fd51-13e8-4f83-a1f8-8107bbd5257d', 'e43a9e37-44de-43a4-8c70-41982bfcdf63', 2, 'Only Execution Environment build configuration');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('22595d03-6caf-48b7-a6a5-059f89c4a0e8', 'e43a9e37-44de-43a4-8c70-41982bfcdf63', 3, 'Kubernetes cluster configuration for K8s-targeted playbooks');
