INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9a17c170-579c-4b69-96ba-e203002c6f2f', 'ad515323-6e49-4d81-b70d-977c942959da', 0, 'They are exact synonyms with no functional difference');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7ec89d2b-5aeb-4f6d-b024-211c0c62376d', 'ad515323-6e49-4d81-b70d-977c942959da', 1, '`settings` reviews ansible-navigator''s own current settings (from defaults/settings file/env vars/CLI); `config` reviews the underlying Ansible configuration (ansible.cfg-driven)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d8856321-dae6-433f-91c0-0f285b1b05d4', 'ad515323-6e49-4d81-b70d-977c942959da', 2, '`settings` only works in interactive mode; `config` only works in stdout mode');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f479221f-ed8d-4df1-839b-7ce172820893', 'ad515323-6e49-4d81-b70d-977c942959da', 3, '`config` is deprecated in favor of `settings` and no longer functions');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
