INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('594d7fc8-a58f-4701-b051-9743669f719e', '67218d88-66c7-464e-9c6f-ef4a524286a5', 0, 'Deletes the documentation cache for that module');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e29ac17e-6b02-4866-a0e2-8d93fb9ba56c', '67218d88-66c7-464e-9c6f-ef4a524286a5', 1, 'Reviews the documentation for the named module or plugin, similar in purpose to the standalone `ansible-doc` command but through navigator''s interface');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ee70ec0e-2c57-42a1-865d-ef8555aca1a7', '67218d88-66c7-464e-9c6f-ef4a524286a5', 2, 'Publishes documentation to Ansible Galaxy');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c5e56c24-2319-4f48-94cf-5e71bb0ebdb0', '67218d88-66c7-464e-9c6f-ef4a524286a5', 3, 'Only works for modules in the ansible.builtin collection');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
