INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5f1b094d-fb96-4c4b-b993-8807e57d30b3', '51ce929a-d469-489c-b6db-1a1975a7e6ba', 0, 'exec runs an arbitrary command inside the configured Execution Environment container, rather than running an Ansible playbook specifically');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('23d69df0-e1e2-43c3-9c99-50a8d64c6600', '51ce929a-d469-489c-b6db-1a1975a7e6ba', 1, 'exec and run are identical aliases');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8bc6f399-56ef-4eea-83f6-7b9e03baa2bf', '51ce929a-d469-489c-b6db-1a1975a7e6ba', 2, 'exec only works with Kubernetes-based Execution Environments');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9d1c97be-0fc4-44de-9a6b-9aa5177c96be', '51ce929a-d469-489c-b6db-1a1975a7e6ba', 3, 'exec is used exclusively to execute ansible-galaxy commands');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7b10f619-b66f-475a-8866-3256dee65e73', 'be399bf4-62b9-4feb-b29c-d183b1dc364a', 0, 'To install new managed nodes automatically');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9ba67edd-c519-4625-a8c0-eb75ac85d292', 'be399bf4-62b9-4feb-b29c-d183b1dc364a', 1, 'To explore an inventory — browsing groups, hosts, and variables interactively');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dfecae07-3e22-4633-8293-a9fe296d3dba', 'be399bf4-62b9-4feb-b29c-d183b1dc364a', 2, 'To convert a YAML inventory into an INI-format inventory');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a72495f4-0371-4401-89d8-882915e1b958', 'be399bf4-62b9-4feb-b29c-d183b1dc364a', 3, 'To validate playbook syntax against inventory hostnames');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0f325b2b-8fc0-47a9-a739-a9aaf9b528db', '2a53841b-86bc-4f94-9ff4-5f08bbd417e0', 0, 'Re-run a playbook from scratch against live infrastructure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8e8323f4-6d46-43a5-bb09-aba0e10b7cb7', '2a53841b-86bc-4f94-9ff4-5f08bbd417e0', 1, 'Explore a previous run using its saved playbook artifact, without re-executing anything against real hosts');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4c36b73b-caf3-4bf7-b60d-10126c09ce9d', '2a53841b-86bc-4f94-9ff4-5f08bbd417e0', 2, 'Replay a playbook''s Jinja2 templates step-by-step in a debugger');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0a54e35f-876b-413e-b71c-96a0696935d1', '2a53841b-86bc-4f94-9ff4-5f08bbd417e0', 3, 'Restore a previous Execution Environment image version');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dd209775-856f-4afc-9756-9779a48ed9db', '63a1b388-656b-43d2-bd2b-6d88332e2818', 0, 'It only checks whether an Execution Environment image is signed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4df4a2f9-5f37-430e-b38c-cb3d5fb3950e', '63a1b388-656b-43d2-bd2b-6d88332e2818', 1, 'It lints a file or directory for common errors and issues, similar in spirit to running ansible-lint directly, through navigator''s interface');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('06721ca0-45e6-46c4-83f6-bf36bde63a61', '63a1b388-656b-43d2-bd2b-6d88332e2818', 2, 'It compiles a playbook into a binary artifact');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9296f308-c2c1-464d-ba9f-51a011060a14', '63a1b388-656b-43d2-bd2b-6d88332e2818', 3, 'It is a synonym for `ansible-navigator run --check`');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d8d37875-a97d-4bf4-9347-b79ddec1c3e9', '6ca3e1b8-83d0-4afd-8e74-41cfa15f4a74', 0, 'Because ansible-navigator cannot run playbooks without a container runtime under any configuration');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5f596c92-76ac-476b-9e71-015164a9ebbf', '6ca3e1b8-83d0-4afd-8e74-41cfa15f4a74', 1, 'Because defaulting to EE-based execution means the collections/dependencies used for a run are the pinned, portable set baked into the image, rather than depending on whatever happens to be installed locally — directly addressing the dependency-drift problem EEs exist to solve');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('38c1b41c-2c72-4029-8047-7e2776dad478', '6ca3e1b8-83d0-4afd-8e74-41cfa15f4a74', 2, 'Because EEs make ansible-navigator run without needing an inventory');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('731f7c73-430a-4909-be3c-a0a7b0082458', '6ca3e1b8-83d0-4afd-8e74-41cfa15f4a74', 3, 'Because Red Hat requires all Ansible tooling to run exclusively in containers as of RHEL 9');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
